470	      if (f.el.value === submitted[f.key]) {
471	        // 等待期间未再改动：同步为服务端保存的规范值（例如去首尾空白后的标题）。
472	        if (f.el.value !== f.value) f.el.value = f.value;
473	      } else {
474	        // 等待期间又被修改（包括清空摘要或正文）：保留当前输入，不动一个字符。
475	        // 仅当保留下来的当前值确实与本次已保存值不同时，才算仍有未保存修改。
476	        if (f.el.value !== f.value) editedWhileSaving.push(f.label);
