495	      setStatus('修改已保存。文章标识、创建时间与草稿状态均未改变。', 'ok');
496	    } else {
497	      setStatus('本次提交的内容已保存（文章标识、创建时间与草稿状态不变）。但'
498	        + editedWhileSaving.join('、')
499	        + '在保存期间又被修改，这些新输入尚未保存；再次点击“保存修改”才会一并存入同一篇草稿。', 'warn');
