540	interface Article {
541	  id: string;
542	  title: string;
543	  summary: string;
544	  body: string;
545	  status: 'draft';
546	  createdAt: string;
547	  version: number;
548	}
549	interface StoredArticle {
550	  id?: unknown;
551	  title?: unknown;
552	  summary?: unknown;
553	  body?: unknown;
554	  status?: unknown;
555	  createdAt?: unknown;
556	  version?: unknown;
557	}
558	interface DraftInput {
559	  title: string;
560	  summary: string;
561	  body: string;
562	}
