573	function respond(res: ServerResponse, status: number, value: unknown, html = false): void {
574	  const body = html ? String(value) : JSON.stringify(value);
575	  res.writeHead(status, {
576	    'content-type': html ? 'text/html; charset=utf-8' : 'application/json; charset=utf-8',
577	    'content-length': Buffer.byteLength(body),
