592	// Normalize a stored record. Drafts saved by older versions have no `version`
593	// field; those are treated as version 0 and can be opened and edited directly.
594	function normalizeArticle(record: unknown): Article | null {
595	  if (typeof record !== 'object' || record === null || Array.isArray(record)) return null;
596	  const r = record as StoredArticle;
597	  if (typeof r.id !== 'string' || typeof r.title !== 'string' || typeof r.body !== 'string') return null;
598	  if (r.status !== 'draft' || typeof r.createdAt !== 'string') return null;
599	  const version = typeof r.version === 'number' && Number.isInteger(r.version) && r.version >= 0 ? r.version : 0;
600	  return {
601	    id: r.id,
602	    title: r.title,
603	    summary: typeof r.summary === 'string' ? r.summary : '',
604	    body: r.body,
605	    status: 'draft',
606	    createdAt: r.createdAt,
607	    version,
608	  };
609	}
