611	function readArticles(): Article[] {
612	  let parsed: unknown;
613	  try {
614	    parsed = JSON.parse(readFileSync(dataFile, 'utf8'));
615	  } catch (error) {
616	    throw new Error(`unable to read articles: ${(error as Error).message}`);
617	  }
618	  if (!Array.isArray(parsed)) throw new Error('unable to read articles: stored data is not a list');
619	  const articles: Article[] = [];
620	  for (const record of parsed) {
621	    const article = normalizeArticle(record);
622	    if (article) articles.push(article);
623	  }
624	  return articles;
625	}
626	
627	function writeArticles(records: Article[]): void {
628	  const tmpFile = join(dataDir, `.articles.${process.pid}.tmp`);
629	  try {
630	    writeFileSync(tmpFile, `${JSON.stringify(records, null, 2)}\n`);
631	    renameSync(tmpFile, dataFile);
632	  } catch (error) {
633	    try { rmSync(tmpFile, { force: true }); } catch { /* best effort cleanup */ }
634	    throw new Error(`unable to save articles: ${(error as Error).message}`);
635	  }
636	}
