809	      const records = readArticles();
810	      records.push(article);
811	      writeArticles(records);
812	    });
813	    respond(res, 201, { article });
814	    return;
815	  }
816	  methodNotAllowed(res, 'GET, POST');
817	}
818	
819	const server = createServer((req: IncomingMessage, res: ServerResponse): void => {
820	  handle(req, res).catch((error: unknown) => {
