  function fetchStub(url, opts) {
    calls.push({ url, opts });
    if (url === '/api/articles' && (!opts || opts.method === undefined)) {
      return Promise.resolve({
        ok: true, status: 200,
        json: () => Promise.resolve({ articles: [] }),
      });
