  check('D: still in create mode (POST would happen again)', els['save-btn'].textContent === '保存草稿');
  check('D: error status with reason', els.status.className.includes('err') && els.status.textContent.includes('boom disk'), els.status.textContent);
  els['draft-form'].handlers.submit({ preventDefault() {} });
